-- Add experienced-lifter programs; existing sessions and programs remain unchanged.
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('barbell-squat','barbell-squat','Barbell back squat','Use a rack with safeties and a qualified spotter. Brace before descent; keep a controlled pain-free range. Finish with 2–3 repetitions in reserve.','BARBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('bench-press','bench-press','Barbell bench press','Use rack safeties or a spotter. Keep feet stable and shoulder blades supported. Lower under control; avoid maximal attempts.','BARBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('romanian-deadlift','romanian-deadlift','Romanian deadlift','Brace and hinge at the hips with a neutral trunk. Stop when hamstring tension limits the range; avoid rounding.','BARBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('lat-pulldown','lat-pulldown','Lat pulldown','Keep torso stable. Pull toward the upper chest without jerking or pulling behind the neck.','MACHINE','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('split-squat','split-squat','Dumbbell split squat','Use a stable split stance. Lower under control; use support if balance is limited. Repetitions are per side.','DUMBBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('overhead-press','overhead-press','Seated dumbbell press','Use manageable dumbbells and back support. Press in a comfortable arc without forcing shoulder range.','DUMBBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('cable-row','cable-row','Seated cable row','Keep ribs controlled and torso stable. Pull elbows back without swinging.','MACHINE','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('leg-curl','leg-curl','Machine leg curl','Adjust machine to fit knee alignment. Curl smoothly without lifting the hips.','MACHINE','STRENGTH');
INSERT OR IGNORE INTO FitnessExercise(id,slug,name,instructions,equipment,category) VALUES('lateral-raise','lateral-raise','Dumbbell lateral raise','Use light weights; raise in a comfortable plane without shrugging or swinging.','DUMBBELL','STRENGTH');
INSERT OR IGNORE INTO FitnessProgram(id,title,description,level,status,content,minutes) VALUES('advanced-upper-strength','Advanced Upper: Strength','Advanced upper-body strength session. Pair with lower-body strength and upper/lower volume sessions over four days weekly. Keep 48 hours between repeated muscle groups. Weeks 1–3 use 2–3 RIR; week 4 reduce sets by 40%. Increase load only after all prescribed reps are completed comfortably in two sessions; no progression during pain, poor sleep or unusual fatigue.','ADVANCED','PUBLISHED','[{"exerciseId": "bench-press", "sets": 4, "reps": 6, "rest": 180, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "cable-row", "sets": 4, "reps": 8, "rest": 120, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "overhead-press", "sets": 3, "reps": 8, "rest": 120, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "lat-pulldown", "sets": 3, "reps": 10, "rest": 90, "tempo": "Controlled 2-second lowering"}]',60);
INSERT OR IGNORE INTO FitnessProgram(id,title,description,level,status,content,minutes) VALUES('advanced-lower-strength','Advanced Lower: Strength','Lower-body strength session for experienced lifters with sound technique. Alternate with upper-body days. Work at 2–3 RIR, never to failure on compound lifts. Four-week block: three gradual weeks and one deload with 40% fewer sets. Increase by the smallest available load only after two comfortable successful sessions. Stop for pain; seek coaching for unfamiliar lifts.','ADVANCED','PUBLISHED','[{"exerciseId": "barbell-squat", "sets": 4, "reps": 6, "rest": 180, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "romanian-deadlift", "sets": 3, "reps": 8, "rest": 150, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "split-squat", "sets": 3, "reps": 8, "rest": 120, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "leg-curl", "sets": 3, "reps": 12, "rest": 90, "tempo": "Controlled 2-second lowering"}]',60);
INSERT OR IGNORE INTO FitnessProgram(id,title,description,level,status,content,minutes) VALUES('advanced-upper-volume','Advanced Upper: Hypertrophy','Upper-body volume session for the four-day upper/lower split. Use controlled 2-second lowering, 2 RIR and stable technique. Complete all repetitions before considering a small load increase on a later session. Rest at least 48 hours before repeating. Deload every fourth week or earlier if recovery deteriorates.','ADVANCED','PUBLISHED','[{"exerciseId": "bench-press", "sets": 3, "reps": 10, "rest": 120, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "lat-pulldown", "sets": 4, "reps": 10, "rest": 90, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "cable-row", "sets": 3, "reps": 12, "rest": 90, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "lateral-raise", "sets": 3, "reps": 15, "rest": 60, "tempo": "Controlled 2-second lowering"}]',55);
INSERT OR IGNORE INTO FitnessProgram(id,title,description,level,status,content,minutes) VALUES('advanced-lower-volume','Advanced Lower: Hypertrophy','Lower-body volume day for the four-day split. Use 2–3 RIR and moderate loads. Split-squat repetitions are per side. Record the dumbbell pair total consistently. Reduce training when recovery is poor. Every fourth week reduce sets by 40%; never force extra load to match a report.','ADVANCED','PUBLISHED','[{"exerciseId": "barbell-squat", "sets": 3, "reps": 10, "rest": 150, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "romanian-deadlift", "sets": 3, "reps": 10, "rest": 120, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "split-squat", "sets": 3, "reps": 12, "rest": 90, "tempo": "Controlled 2-second lowering"}, {"exerciseId": "leg-curl", "sets": 4, "reps": 12, "rest": 90, "tempo": "Controlled 2-second lowering"}]',55);
